<script setup>
import { computed, onMounted, ref } from "vue";
import { ArchiveRestore, BarChart3, ChevronDown, ChevronUp, ClipboardList, Eye, FolderTree, Link2, LogIn, LogOut, Package, Plus, Save, Settings, Trash2, Upload } from "@lucide/vue";

const loggedIn=ref(false), initialized=ref(false), rememberCredentials=ref(false), credentials=ref({username:"admin",password:""}), error=ref(""), notice=ref(""), tab=ref("dashboard");
const rememberedCredentialsKey="softwarehub.admin.credentials";
function loadRememberedCredentials(){try{const saved=JSON.parse(localStorage.getItem(rememberedCredentialsKey)||"null");if(saved?.username){credentials.value.username=String(saved.username);rememberCredentials.value=true;localStorage.setItem(rememberedCredentialsKey,JSON.stringify({username:credentials.value.username}))}}catch{localStorage.removeItem(rememberedCredentialsKey)}}
function persistRememberedCredentials(){if(rememberCredentials.value)localStorage.setItem(rememberedCredentialsKey,JSON.stringify({username:credentials.value.username}));else localStorage.removeItem(rememberedCredentialsKey)}
const software=ref([]), categories=ref([]), settings=ref({}), statistics=ref(null), announcements=ref([]), slides=ref([]), media=ref([]), auditLogs=ref([]), editing=ref(null), editingCategory=ref(null), editingAnnouncement=ref(null), editingSlide=ref(null), links=ref([]), versions=ref([]);
const accountForm=ref({username:"",currentPassword:"",newPassword:""}), selectedSoftware=ref([]), linkCheckResults=ref([]), importText=ref("");
const homepageSectionLabels={announcements:"公告",carousel:"轮播",recommended:"推荐",updated:"最近更新",categories:"分类分区"};
const homepageSectionOrder=computed(()=>{try{const value=JSON.parse(settings.value.homepage_sections||"[]");return Array.isArray(value)&&value.length?value:["announcements","carousel","recommended","updated","categories"]}catch{return ["announcements","carousel","recommended","updated","categories"]}});
const footerLinksDraft=ref([]);
function syncFooterLinks(){try{const value=JSON.parse(settings.value.footer_links||"[]");footerLinksDraft.value=Array.isArray(value)?value.map(link=>({name:String(link?.name||""),url:String(link?.url||"")})):[]}catch{footerLinksDraft.value=[]}}
const platforms=["Windows","macOS","Android","iOS","Linux","HarmonyOS","Web","ChromeOS","飞牛 NAS"];
const maintenance=[{value:"MAINTAINED",label:"长期维护"},{value:"BETA",label:"内测版"},{value:"LIMITED",label:"有限维护"},{value:"DEPRECATED",label:"停止维护"},{value:"RISK",label:"风险提示"}];
const emptySoftware=()=>({name:"",slug:"",categoryId:null,version:"",platforms:["Windows"],fileSize:"",summary:"",description:"",tutorial:"",changelog:"",downloadNote:"",coverImage:"",screenshots:[],tags:[],publishAt:"",unpublishAt:"",unfeatureAt:"",chargeType:"FREE",priceCents:0,status:"DRAFT",featured:false,sortOrder:0,maintenanceStatus:"MAINTAINED",maintenanceNote:"",seoTitle:"",seoDescription:"",seoKeywords:"",ogTitle:"",ogDescription:"",ogImage:""});
const emptyLink=()=>({name:"",channelType:"OFFICIAL",targetUrl:"",extractCode:"",requirePurchase:false,sortOrder:0,status:"ACTIVE"});
const emptyVersion=()=>({version:"",fileSize:"",changelog:"",sortOrder:0,status:"ACTIVE"});
const emptyCategory=()=>({name:"",slug:"",sortOrder:0,status:true});
const emptyAnnouncement=()=>({title:"",content:"",sortOrder:0,status:true});
const emptySlide=()=>({imageUrl:"",kicker:"",title:"",content:"",targetType:"CATEGORY",targetValue:"",sortOrder:0,status:true});
const linkForm=ref(emptyLink()), versionForm=ref(emptyVersion()), versionLinkForms=ref({});
const chartPoints=computed(()=>{const data=statistics.value?.series||[];if(!data.length)return "";const max=Math.max(1,...data.map(item=>item.downloads));return data.map((item,index)=>`${index/(data.length-1)*100},${100-item.downloads/max*86-7}`).join(" ")});
const chartLabels=computed(()=>{const data=statistics.value?.series||[];return data.filter((_,index)=>index===0||index===data.length-1||index%7===0)});
function displayTime(value){return value?new Date(value).toLocaleString("zh-CN",{hour12:false}):"—"}
function scheduleInput(value){if(!value)return "";const date=new Date(value);if(Number.isNaN(date.getTime()))return "";const local=new Date(date.getTime()-date.getTimezoneOffset()*60_000);return local.toISOString().slice(0,16)}
function displayAgent(value){if(!value)return "—";if(/Edg\//.test(value))return "Edge";if(/Chrome\//.test(value))return "Chrome";if(/Firefox\//.test(value))return "Firefox";if(/Safari\//.test(value))return "Safari";return value.slice(0,42)}
async function api(path,options={}){try{const r=await fetch(path,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options});if(r.status===401)loggedIn.value=false;const text=await r.text();return{ok:r.ok,status:r.status,data:text?JSON.parse(text):{}}}catch{return{ok:false,status:0,data:{}}}}
function alert(text,failed=false){if(failed){error.value=text;notice.value=""}else{notice.value=text;error.value=""}}
async function loadAll(){const [s,c,st,stats,a,sl,me]=await Promise.all([api("/api/admin/software"),api("/api/admin/categories"),api("/api/admin/settings"),api("/api/admin/statistics"),api("/api/admin/announcements"),api("/api/admin/slides"),api("/api/admin/me")]);if(s.ok)software.value=s.data;if(c.ok)categories.value=c.data;if(st.ok){settings.value=st.data;syncFooterLinks()}if(stats.ok)statistics.value=stats.data;if(a.ok)announcements.value=a.data;if(sl.ok)slides.value=sl.data;if(me.ok)accountForm.value.username=me.data.username;if(!s.ok||!c.ok)alert("后台数据加载失败",true)}
async function login(){const r=await api("/api/admin/login",{method:"POST",body:JSON.stringify(credentials.value)});if(!r.ok)return alert("账号或密码错误",true);persistRememberedCredentials();loggedIn.value=true;await loadAll()}
async function logout(){await api("/api/admin/logout",{method:"POST"});loggedIn.value=false}
async function editSoftware(item=null){editing.value=item?{...item,categoryId:item.category_id,fileSize:item.file_size,chargeType:item.charge_type,priceCents:item.price_cents,coverImage:item.cover_image,screenshots:[...(item.screenshots||[])],featured:!!item.featured,sortOrder:item.sort_order||0,maintenanceStatus:item.maintenance_status||"MAINTAINED",maintenanceNote:item.maintenance_note||"",downloadNote:item.download_note||"",tags:[...(item.tags||[])],publishAt:scheduleInput(item.publish_at),unpublishAt:scheduleInput(item.unpublish_at),unfeatureAt:scheduleInput(item.unfeature_at),seoTitle:item.seo_title||"",seoDescription:item.seo_description||"",seoKeywords:item.seo_keywords||"",ogTitle:item.og_title||"",ogDescription:item.og_description||"",ogImage:item.og_image||""}:emptySoftware();links.value=[];versions.value=[];linkForm.value=emptyLink();versionForm.value=emptyVersion();versionLinkForms.value={};if(item)await Promise.all([loadLinks(item.id),loadVersions(item.id)])}
async function saveSoftware(){const x=editing.value,r=await api(x.id?`/api/admin/software/${x.id}`:"/api/admin/software",{method:x.id?"PUT":"POST",body:JSON.stringify(x)});if(!r.ok)return alert("应用保存失败，请检查名称和固定链接",true);alert("应用已保存");if(!x.id){editing.value=null}else await loadAll()}
async function deleteSoftware(x){if(!confirm(`确定删除“${x.name}”及其下载渠道、版本历史吗？此操作不可恢复。`))return;const r=await api(`/api/admin/software/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("应用删除失败",true);editing.value=null;await loadAll();alert("应用已删除")}
async function duplicateSoftware(x){const r=await api(`/api/admin/software/${x.id}/duplicate`,{method:"POST"});if(!r.ok)return alert("应用复制失败",true);await loadAll();alert("应用已复制为草稿")}
async function bulkSoftware(action){if(!selectedSoftware.value.length)return alert("请先选择应用",true);const body={ids:selectedSoftware.value};if(action==="delete"&&!confirm("确定删除选中的应用？此操作不可恢复。"))return;if(action==="delete")body.delete=true;if(action==="publish")body.status="PUBLISHED";if(action==="offline")body.status="OFFLINE";if(action==="feature")body.featured=true;if(action==="unfeature")body.featured=false;const r=await api("/api/admin/software/bulk",{method:"POST",body:JSON.stringify(body)});if(!r.ok)return alert("批量操作失败",true);selectedSoftware.value=[];await loadAll();alert("批量操作已完成")}
async function checkAllLinks(){const r=await api("/api/admin/links/check-all",{method:"POST"});if(!r.ok)return alert("全量巡检失败",true);linkCheckResults.value=r.data.results;alert(`巡检完成：${r.data.results.length} 个链接`)}
async function importSoftware(){try{const parsed=JSON.parse(importText.value);const items=Array.isArray(parsed)?parsed:parsed.items;const r=await api("/api/admin/software/import",{method:"POST",body:JSON.stringify({items})});if(!r.ok)return alert("导入失败，请检查 JSON 格式",true);importText.value="";await loadAll();alert(`已导入 ${r.data.created.length} 个应用`)}catch{const r=await api("/api/admin/software/import",{method:"POST",body:JSON.stringify({csv:importText.value})});if(!r.ok)return alert("导入内容不是有效 JSON 或 CSV",true);importText.value="";await loadAll();alert(`已导入 ${r.data.created.length} 个应用`)}}
function previewSoftware(){window.open(`/preview/${editing.value.id}`,"_blank")}
async function loadLinks(id){const r=await api(`/api/admin/software/${id}/links`);if(r.ok)links.value=r.data}
async function saveLink(x){const create=!x.id,r=await api(create?`/api/admin/software/${editing.value.id}/links`:`/api/admin/software/${editing.value.id}/links/${x.id}`,{method:create?"POST":"PUT",body:JSON.stringify(create?x:{name:x.name,channelType:x.channel_type,targetUrl:x.target_url,extractCode:x.extract_code,requirePurchase:x.require_purchase,sortOrder:x.sort_order,status:x.status})});if(!r.ok)return alert("下载渠道保存失败",true);linkForm.value=emptyLink();await loadLinks(editing.value.id);alert("下载渠道已保存")}
async function deleteLink(x){if(!confirm(`删除下载渠道“${x.name}”？`))return;const r=await api(`/api/admin/software/${editing.value.id}/links/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("下载渠道删除失败",true);await loadLinks(editing.value.id);alert("下载渠道已删除")}
async function checkLink(x){const r=await api(`/api/admin/software/${editing.value.id}/links/${x.id}/check`,{method:"POST"});if(!r.ok)return alert("链接检测失败",true);await loadLinks(editing.value.id);alert(`检测完成：${r.data.message}`,r.data.status!=="OK")}
async function loadVersions(id){const r=await api(`/api/admin/software/${id}/versions`);if(r.ok){versions.value=r.data;for(const v of versions.value)versionLinkForms.value[v.id]={name:"",targetUrl:"",sortOrder:0,status:"ACTIVE"}}}
async function saveVersion(x){const create=!x.id,r=await api(create?`/api/admin/software/${editing.value.id}/versions`:`/api/admin/software/${editing.value.id}/versions/${x.id}`,{method:create?"POST":"PUT",body:JSON.stringify(create?x:{version:x.version,fileSize:x.file_size,changelog:x.changelog,sortOrder:x.sort_order,status:x.status})});if(!r.ok)return alert("版本保存失败",true);versionForm.value=emptyVersion();await loadVersions(editing.value.id);alert("版本历史已保存")}
async function deleteVersion(x){if(!confirm(`删除历史版本 ${x.version} 及其下载链接？`))return;const r=await api(`/api/admin/software/${editing.value.id}/versions/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("历史版本删除失败",true);await loadVersions(editing.value.id);alert("历史版本已删除")}
async function addVersionLink(v){const form=versionLinkForms.value[v.id],r=await api(`/api/admin/versions/${v.id}/links`,{method:"POST",body:JSON.stringify(form)});if(!r.ok)return alert("历史下载链接保存失败",true);await loadVersions(editing.value.id);alert("历史下载链接已添加")}
async function deleteVersionLink(v,x){if(!confirm(`删除“${x.name}”？`))return;const r=await api(`/api/admin/versions/${v.id}/links/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("历史下载链接删除失败",true);await loadVersions(editing.value.id)}
async function uploadImage(e,apply){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>2*1024*1024){e.target.value="";return alert("仅支持 2 MB 内 PNG、JPEG 或 WebP",true)}const dataUrl=await new Promise((ok,no)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=no;reader.readAsDataURL(file)}),r=await api("/api/admin/upload",{method:"POST",body:JSON.stringify({dataUrl})});e.target.value="";if(!r.ok)return alert("图片上传失败",true);apply(r.data.url);alert("图片上传成功")}
function moveScreenshot(i,d){const list=editing.value.screenshots,target=i+d;if(target<0||target>=list.length)return;[list[i],list[target]]=[list[target],list[i]]}
function editCategory(x=null){editingCategory.value=x?{...x,status:!!x.status,sortOrder:x.sort_order||0}:emptyCategory()}
async function saveCategory(){const x=editingCategory.value,r=await api(x.id?`/api/admin/categories/${x.id}`:"/api/admin/categories",{method:x.id?"PUT":"POST",body:JSON.stringify(x)});if(!r.ok)return alert("分类保存失败",true);editingCategory.value=null;await loadAll();alert("分类已保存")}
async function deleteCategory(x){if(!confirm(`删除分类“${x.name}”？`))return;const r=await api(`/api/admin/categories/${x.id}`,{method:"DELETE"});if(!r.ok)return alert(r.status===409?"分类仍被应用使用，不能删除":"分类删除失败",true);await loadAll();alert("分类已删除")}
function editAnnouncement(x=null){editingAnnouncement.value=x?{...x,status:!!x.status,sortOrder:x.sort_order||0}:emptyAnnouncement()}
async function saveAnnouncement(){const x=editingAnnouncement.value,r=await api(x.id?`/api/admin/announcements/${x.id}`:"/api/admin/announcements",{method:x.id?"PUT":"POST",body:JSON.stringify(x)});if(!r.ok)return alert("公告保存失败",true);editingAnnouncement.value=null;await loadAll();alert("公告已保存")}
async function deleteAnnouncement(x){if(!confirm(`删除公告“${x.title}”？`))return;const r=await api(`/api/admin/announcements/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("公告删除失败",true);await loadAll();alert("公告已删除")}
async function saveSettings(){settings.value.homepage_sections=JSON.stringify(homepageSectionOrder.value);settings.value.footer_links=JSON.stringify(footerLinksDraft.value.filter(link=>link.name||link.url));const r=await api("/api/admin/settings",{method:"PUT",body:JSON.stringify(settings.value)});alert(r.ok?"站点设置已保存":"站点设置保存失败",!r.ok)}
function moveHomepageSection(index,direction){const order=[...homepageSectionOrder.value],target=index+direction;if(target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]];settings.value.homepage_sections=JSON.stringify(order)}
function addFooterLink(){footerLinksDraft.value.push({name:"",url:""})}
function removeFooterLink(index){footerLinksDraft.value.splice(index,1)}
async function moveSlide(index,direction){const list=[...slides.value],target=index+direction;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];list.forEach((item,i)=>{item.sort_order=(i+1)*10});slides.value=list;const results=await Promise.all(list.map(item=>api(`/api/admin/slides/${item.id}`,{method:"PUT",body:JSON.stringify({imageUrl:item.image_url,kicker:item.kicker,title:item.title,content:item.content,targetType:item.target_type,targetValue:item.target_value,sortOrder:item.sort_order,status:!!item.status})})));if(results.some(result=>!result.ok)){await loadAll();return alert("轮播顺序保存失败，已恢复服务器顺序",true)}alert("轮播顺序已保存")}
async function uploadSettingImage(e,key){await uploadImage(e,url=>settings.value[key]=url)}
function editSlide(x=null){editingSlide.value=x?{...x,imageUrl:x.image_url,targetType:x.target_type,targetValue:x.target_value,sortOrder:x.sort_order||0,status:!!x.status}:emptySlide()}
async function saveSlide(){const x=editingSlide.value,r=await api(x.id?`/api/admin/slides/${x.id}`:"/api/admin/slides",{method:x.id?"PUT":"POST",body:JSON.stringify(x)});if(!r.ok)return alert("轮播图保存失败",true);editingSlide.value=null;await loadAll();alert("轮播图已保存")}
async function deleteSlide(x){if(!confirm(`删除轮播图“${x.title}”？`))return;const r=await api(`/api/admin/slides/${x.id}`,{method:"DELETE"});if(!r.ok)return alert("轮播图删除失败",true);await loadAll();alert("轮播图已删除")}
async function loadMedia(){const r=await api("/api/admin/media");if(r.ok)media.value=r.data;else alert("媒体列表加载失败",true)}
async function deleteMedia(x){if(x.referenced)return alert("该图片仍被内容引用，不能删除",true);if(!confirm(`删除未引用图片 ${x.name}？`))return;const r=await api(`/api/admin/media/${encodeURIComponent(x.name)}`,{method:"DELETE"});if(!r.ok)return alert("图片删除失败",true);await loadMedia();alert("图片已删除")}
async function loadAuditLogs(){const r=await api("/api/admin/audit-logs");if(r.ok)auditLogs.value=r.data;else alert("操作日志加载失败",true)}
async function saveAccount(){const r=await api("/api/admin/account",{method:"PUT",body:JSON.stringify(accountForm.value)});if(!r.ok)return alert(r.data.error==="CURRENT_PASSWORD_INVALID"?"当前密码错误":"账户保存失败，请检查用户名和新密码",true);accountForm.value.currentPassword="";accountForm.value.newPassword="";alert("管理员账户已更新")}
async function exportDownloads(){const r=await fetch("/api/admin/downloads.csv");if(!r.ok)return alert("下载统计导出失败",true);const url=URL.createObjectURL(await r.blob()),a=document.createElement("a");a.href=url;a.download="softwarehub-downloads.csv";a.click();URL.revokeObjectURL(url);alert("下载统计已导出")}
async function archiveBackup(){const r=await api("/api/admin/backup/archive",{method:"POST"});alert(r.ok?`本地备份已创建，保留 ${r.data.kept} 份`:"本地备份创建失败",!r.ok)}
async function exportBackup(){const r=await api("/api/admin/backup");if(!r.ok)return alert("备份导出失败",true);const a=document.createElement("a"),url=URL.createObjectURL(new Blob([JSON.stringify(r.data,null,2)],{type:"application/json"}));a.href=url;a.download=`softwarehub-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);alert("备份已导出")}
async function restoreBackup(e){const file=e.target.files?.[0];e.target.value="";if(!file||!confirm("恢复会替换当前站点数据，确定继续吗？"))return;try{const r=await api("/api/admin/restore",{method:"POST",body:await file.text()});if(!r.ok)return alert("备份文件无效或恢复失败",true);await loadAll();alert("数据已恢复")}catch{alert("无法读取备份文件",true)}}
onMounted(async()=>{loadRememberedCredentials();const r=await api("/api/admin/me");loggedIn.value=r.ok;if(r.ok)await loadAll();initialized.value=true})
</script>
<template>
<section v-if="!initialized" class="admin-login admin-loading" aria-live="polite"><div class="login-panel"><span class="brand-mark large"><Settings :size="24"/></span><p>正在验证登录状态…</p></div></section>
<section v-else-if="!loggedIn" class="admin-login"><form class="login-panel" @submit.prevent="login"><span class="brand-mark large"><LogIn :size="24"/></span><h1>管理后台</h1><p>维护应用、版本、分类、公告与备份。</p><label>管理员账号<input v-model="credentials.username" autocomplete="username"/></label><label>密码<input v-model="credentials.password" type="password" autocomplete="current-password"/></label><label class="checkbox remember-login"><input v-model="rememberCredentials" type="checkbox" @change="persistRememberedCredentials"/>记住管理员账号</label><p v-if="error" class="form-error">{{error}}</p><button class="primary-button wide">登录</button></form></section>
<section v-else class="admin-shell"><aside class="admin-sidebar"><h1>站点管理</h1><button :class="{active:tab==='dashboard'}" @click="tab='dashboard'"><BarChart3 :size="18"/>概览统计</button><button :class="{active:tab==='software'}" @click="tab='software'"><Package :size="18"/>应用管理</button><button :class="{active:tab==='categories'}" @click="tab='categories'"><FolderTree :size="18"/>分类管理</button><button :class="{active:tab==='announcements'}" @click="tab='announcements'"><ClipboardList :size="18"/>站内公告</button><button :class="{active:tab==='slides'}" @click="tab='slides'"><Eye :size="18"/>首页轮播</button><button :class="{active:tab==='links'}" @click="tab='links'"><Link2 :size="18"/>链接巡检</button><button :class="{active:tab==='settings'}" @click="tab='settings'"><Settings :size="18"/>运营与安全</button><button :class="{active:tab==='maintenance'}" @click="tab='maintenance';loadMedia();loadAuditLogs()"><ArchiveRestore :size="18"/>数据维护</button><button class="logout-button" @click="logout"><LogOut :size="18"/>退出登录</button></aside><main class="admin-main"><p v-if="notice" class="admin-notice">{{notice}}</p><p v-if="error" class="form-error">{{error}}</p>
<template v-if="tab==='dashboard'"><div class="admin-heading"><div><p class="eyebrow">数据概览</p><h2>下载统计</h2></div><button class="secondary-button" @click="loadAll">刷新</button></div><div v-if="statistics" class="stats-grid"><article><span>应用总数</span><strong>{{statistics.overview.software}}</strong></article><article><span>已发布</span><strong>{{statistics.overview.published}}</strong></article><article><span>累计下载</span><strong>{{statistics.overview.downloads}}</strong></article><article><span>近 30 天下载</span><strong>{{statistics.overview.downloads30d}}</strong></article></div><div class="dashboard-grid"><section class="admin-panel"><div class="panel-title"><h3>热门访问</h3><span>近 30 天</span></div><ul class="update-list"><li v-for="item in statistics.views" :key="item.id"><span>{{item.name}}</span><strong>{{item.views}}</strong></li></ul></section><section class="admin-panel"><div class="panel-title"><h3>搜索词</h3><span>无结果可补录</span></div><ul class="update-list"><li v-for="item in statistics.searches" :key="item.query"><span>{{item.query}}</span><small>{{item.searches}} 次<span v-if="item.no_results"> · {{item.no_results}} 次无结果</span></small></li></ul></section></div><template v-if="statistics"><section class="admin-panel download-chart"><div class="panel-title"><h3>近 30 天下载趋势</h3><span>真实下载票据核销</span></div><div v-if="statistics.series?.some(x=>x.downloads)" class="chart-wrap"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="近 30 天下载折线图"><line x1="0" y1="93" x2="100" y2="93" class="chart-axis"/><polyline :points="chartPoints" class="chart-line" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels"><span v-for="item in chartLabels" :key="item.date">{{item.date.slice(5)}}</span></div></div><p v-else class="muted">暂无下载记录，用户完成下载跳转后会在这里生成趋势。</p></section><section class="admin-panel download-log-panel"><div class="panel-title"><h3>最近下载列表</h3><span>{{statistics.downloads?.length||0}} 条</span></div><div v-if="statistics.downloads?.length" class="admin-table-wrap"><table class="admin-table download-log"><thead><tr><th>时间</th><th>下载内容</th><th>通道</th><th>来源 IP</th><th>浏览器</th></tr></thead><tbody><tr v-for="item in statistics.downloads" :key="item.id"><td>{{displayTime(item.created_at)}}</td><td><strong>{{item.software_name}}</strong><small>/{{item.software_slug}}</small></td><td>{{item.channel_name}}<small>{{item.channel_type}}</small></td><td class="ip-cell">{{item.client_ip||'旧记录未采集'}}</td><td :title="item.user_agent">{{displayAgent(item.user_agent)}}</td></tr></tbody></table></div><p v-else class="muted">暂无下载记录。</p></section></template></template>
<template v-else-if="tab==='software'"><div class="admin-heading"><div><p class="eyebrow">内容管理</p><h2>应用管理</h2></div><div class="backup-actions"><button class="secondary-button" @click="bulkSoftware('publish')">批量发布</button><button class="secondary-button" @click="bulkSoftware('offline')">批量下架</button><button class="secondary-button" @click="bulkSoftware('feature')">批量推荐</button><button class="primary-button" @click="editSoftware()"><Plus :size="17"/>新增应用</button></div></div><div class="bulk-toolbar"><button class="text-button" @click="selectedSoftware=software.map(x=>x.id)">全选</button><button class="text-button" @click="selectedSoftware=[]">清空选择</button><button class="text-button danger" @click="bulkSoftware('delete')">删除选中</button><span>已选 {{selectedSoftware.length}} 项</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th></th><th>应用</th><th>分类</th><th>状态</th><th>下载</th><th></th></tr></thead><tbody><tr v-for="x in software" :key="x.id"><td><input v-model="selectedSoftware" type="checkbox" :value="x.id"/></td><td><strong>{{x.name}}</strong><small>{{x.slug}} · v{{x.version||'—'}}</small></td><td>{{x.category_name||'未分类'}}</td><td><span class="status-dot" :class="x.status.toLowerCase()">{{x.status}}</span><small>{{x.maintenance_status}}</small></td><td>{{x.download_count}}</td><td><button class="text-button" @click="editSoftware(x)">编辑</button><button class="text-button" @click="duplicateSoftware(x)">复制</button><button class="text-button danger" @click="deleteSoftware(x)">删除</button></td></tr></tbody></table></div><section class="admin-panel import-panel"><div class="panel-title"><h3>批量导入 JSON / CSV</h3><button class="secondary-button" @click="importSoftware">导入应用</button></div><textarea v-model="importText" placeholder='[{"name":"示例","slug":"example","version":"1.0","platforms":["Windows"],"tags":["免费"]}]'></textarea><p class="muted">导入内容会创建为草稿；JSON 支持 links 数组，CSV 首行使用 name,slug,version,platforms,tags,summary,description。</p></section></template>
<template v-else-if="tab==='categories'"><div class="admin-heading"><div><p class="eyebrow">目录维护</p><h2>分类管理</h2></div><button class="primary-button" @click="editCategory()"><Plus :size="17"/>新增分类</button></div><div class="category-admin-list"><article v-for="x in categories" :key="x.id"><div><strong>{{x.name}}</strong><span>/{{x.slug}} · 排序 {{x.sort_order}}</span></div><div><button class="text-button" @click="editCategory(x)">编辑</button><button class="text-button danger" @click="deleteCategory(x)">删除</button></div></article></div></template>
<template v-else-if="tab==='announcements'"><div class="admin-heading"><div><p class="eyebrow">首页通知</p><h2>站内公告</h2></div><button class="primary-button" @click="editAnnouncement()"><Plus :size="17"/>新增公告</button></div><div class="category-admin-list"><article v-for="x in announcements" :key="x.id"><div><strong>{{x.title}}</strong><span>{{x.content}}</span></div><div><button class="text-button" @click="editAnnouncement(x)">编辑</button><button class="text-button danger" @click="deleteAnnouncement(x)">删除</button></div></article></div></template>
<template v-else-if="tab==='slides'"><div class="admin-heading"><div><p class="eyebrow">首页视觉</p><h2>首页轮播</h2></div><button class="primary-button" @click="editSlide()"><Plus :size="17"/>新增轮播图</button></div><div class="category-admin-list"><article v-for="(x,index) in slides" :key="x.id"><div><strong>{{x.title}}</strong><span>{{x.kicker||'无标签'}} · {{x.target_type}} · 排序 {{x.sort_order}} · {{x.status?'启用':'停用'}}</span></div><div><button class="icon-button compact-icon" title="上移" :disabled="index===0" @click="moveSlide(index,-1)"><ChevronUp :size="15"/></button><button class="icon-button compact-icon" title="下移" :disabled="index===slides.length-1" @click="moveSlide(index,1)"><ChevronDown :size="15"/></button><button class="text-button" @click="editSlide(x)">编辑</button><button class="text-button danger" @click="deleteSlide(x)">删除</button></div></article><p v-if="!slides.length" class="muted">还没有轮播图；创建后首页会使用后台内容。</p></div></template>
<template v-else-if="tab==='links'"><div class="admin-heading"><div><p class="eyebrow">运维检查</p><h2>下载链接巡检</h2></div><button class="primary-button" @click="checkAllLinks">立即巡检全部</button></div><section class="admin-panel"><p class="muted">连续失败达到阈值时，系统会按运营配置自动暂停链接。</p><div v-if="linkCheckResults.length" class="check-results"><article v-for="x in linkCheckResults" :key="x.id"><strong>{{x.name}}</strong><span :class="x.status==='OK'?'ok-text':'danger-text'">{{x.status}} · {{x.message}}</span><small>连续失败 {{x.failures}} 次<span v-if="x.autoDisabled">，已自动暂停</span></small></article></div><p v-else class="muted">尚未执行本次巡检。</p></section></template>
<template v-else-if="tab==='settings'"><div class="admin-heading"><div><p class="eyebrow">站点配置</p><h2>运营与安全</h2></div><button class="primary-button" @click="saveSettings"><Save :size="17"/>保存运营配置</button></div><div class="settings-form extended-settings"><section><h3>品牌、页头与页脚</h3><label>站点名称<input v-model="settings.site_name"/></label><label>站点说明<textarea v-model="settings.site_description"/></label><label>默认 SEO 关键词<input v-model="settings.site_seo_keywords" placeholder="软件,下载,应用"/></label><label>站点 Logo<input v-model="settings.site_logo" placeholder="图片地址"/><input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadSettingImage($event,'site_logo')"/></label><label>页脚版权<input v-model="settings.footer_copyright" placeholder="例如：© 2026 软件仓库"/></label><label>备案号<input v-model="settings.footer_icp"/></label><div class="nested-list"><div class="nested-list-title"><strong>页脚外部链接</strong><button class="text-button" type="button" @click="addFooterLink"><Plus :size="14"/>新增</button></div><div v-for="(link,index) in footerLinksDraft" :key="index" class="nested-row"><input v-model="link.name" placeholder="名称"/><input v-model="link.url" placeholder="https://example.com"/><button class="text-button danger" type="button" @click="removeFooterLink(index)"><Trash2 :size="14"/></button></div></div></section><section><h3>首页区块与联系</h3><div class="nested-list"><div class="nested-list-title"><strong>首页区块顺序与开关</strong><span class="muted">使用上下箭头调整顺序</span></div><div v-for="(section,index) in homepageSectionOrder" :key="section" class="nested-row section-order-row"><label class="checkbox"><input v-model="settings[`homepage_show_${section}`]" true-value="1" false-value="0" type="checkbox"/>{{homepageSectionLabels[section]}}</label><button class="icon-button compact-icon" type="button" title="上移" :disabled="index===0" @click="moveHomepageSection(index,-1)"><ChevronUp :size="15"/></button><button class="icon-button compact-icon" type="button" title="下移" :disabled="index===homepageSectionOrder.length-1" @click="moveHomepageSection(index,1)"><ChevronDown :size="15"/></button></div></div><label class="checkbox"><input v-model="settings.homepage_show_carousel" true-value="1" false-value="0" type="checkbox"/>展示轮播</label><label class="checkbox"><input v-model="settings.homepage_show_recommended" true-value="1" false-value="0" type="checkbox"/>展示推荐</label><label class="checkbox"><input v-model="settings.homepage_show_updated" true-value="1" false-value="0" type="checkbox"/>展示更新</label><label class="checkbox"><input v-model="settings.homepage_show_categories" true-value="1" false-value="0" type="checkbox"/>展示分类分区</label><label>每分类展示数量<input v-model="settings.homepage_category_limit" type="number" min="1" max="24"/></label><label>推荐数量<input v-model="settings.homepage_recommended_limit" type="number" min="1" max="24"/></label><label>更新数量<input v-model="settings.homepage_updated_limit" type="number" min="1" max="24"/></label><label>联系邮箱<input v-model="settings.contact_email" type="email"/></label><label>GitHub / 官网<input v-model="settings.contact_github"/></label><label>反馈链接<input v-model="settings.feedback_url"/></label><label>微信赞助二维码<input v-model="settings.donation_wechat" placeholder="图片地址"/><input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadSettingImage($event,'donation_wechat')"/></label><label>支付宝赞助二维码<input v-model="settings.donation_alipay" placeholder="图片地址"/><input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadSettingImage($event,'donation_alipay')"/></label></section><section><h3>下载、隐私与会话</h3><label>默认下载说明<textarea v-model="settings.default_download_note"/></label><label>下载免责声明<textarea v-model="settings.download_disclaimer"/></label><label>下载票据有效秒数<input v-model="settings.download_ticket_seconds" type="number" min="30" max="3600"/></label><label class="checkbox"><input v-model="settings.record_download_metadata" true-value="1" false-value="0" type="checkbox"/>记录下载来源 IP 与浏览器</label><label>会话有效小时数<input v-model="settings.session_hours" type="number" min="1" max="720"/></label><label>登录失败上限<input v-model="settings.login_attempt_limit" type="number" min="3" max="100"/></label><label>登录限制窗口（分钟）<input v-model="settings.login_attempt_window_minutes" type="number" min="1" max="1440"/></label><label class="checkbox"><input v-model="settings.link_auto_disable" true-value="1" false-value="0" type="checkbox"/>链接连续失败后自动暂停</label><label>链接失败阈值<input v-model="settings.link_failure_threshold" type="number" min="1" max="20"/></label><label>自动巡检间隔（小时）<input v-model="settings.link_check_interval_hours" type="number" min="1" max="720"/></label><label>本地备份保留份数<input v-model="settings.backup_retention_count" type="number" min="1" max="100"/></label></section><section><h3>修改管理员账户</h3><label>新管理员账号<input v-model="accountForm.username" autocomplete="username"/></label><label>当前密码<input v-model="accountForm.currentPassword" type="password" autocomplete="current-password"/></label><label>新密码（留空不修改）<input v-model="accountForm.newPassword" type="password" autocomplete="new-password"/></label><button class="secondary-button" @click="saveAccount">更新管理员账户</button></section></div></template>
<template v-else><div class="admin-heading"><div><p class="eyebrow">备份、媒体与审计</p><h2>数据维护</h2></div><div class="backup-actions"><button class="secondary-button" @click="exportDownloads">导出下载 CSV</button><button class="secondary-button" @click="archiveBackup">创建本地备份</button><button class="secondary-button" @click="exportBackup"><ArchiveRestore :size="16"/>导出 JSON 备份</button><label class="secondary-button"><Upload :size="16"/>恢复 JSON 备份<input class="visually-hidden" type="file" accept="application/json" @change="restoreBackup"/></label></div></div><section class="admin-panel"><div class="panel-title"><h3>上传图片</h3><button class="text-button" @click="loadMedia">刷新</button></div><div class="media-list"><article v-for="x in media" :key="x.name"><img :src="x.url" alt=""/><div><strong>{{x.name}}</strong><small>{{Math.ceil(x.size/1024)}} KB · {{x.referenced?'内容引用中':'未引用'}}</small></div><button class="text-button danger" :disabled="x.referenced" @click="deleteMedia(x)">删除</button></article><p v-if="!media.length" class="muted">暂无上传图片。</p></div></section><section class="admin-panel audit-panel"><div class="panel-title"><h3>操作日志</h3><button class="text-button" @click="loadAuditLogs">刷新</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>时间</th><th>账号</th><th>动作</th><th>对象</th><th>来源</th></tr></thead><tbody><tr v-for="x in auditLogs" :key="x.id"><td>{{displayTime(x.created_at)}}</td><td>{{x.username||'已删除账号'}}</td><td>{{x.action}}</td><td>{{x.target_type}} {{x.target_id}}</td><td>{{x.client_ip}}</td></tr></tbody></table></div><p v-if="!auditLogs.length" class="muted">暂无操作记录。</p></section></template>
</main></section>
<div v-if="editing" class="modal-backdrop" @click.self="editing=null"><form class="editor-modal rich-editor" @submit.prevent="saveSoftware"><div class="modal-heading"><div><p class="eyebrow">应用编辑</p><h2>{{editing.id?'编辑应用':'新增应用'}}</h2></div><div><button v-if="editing.id" type="button" class="secondary-button" @click="previewSoftware"><Eye :size="16"/>草稿预览</button><button class="primary-button"><Save :size="17"/>保存</button></div></div><section class="editor-section"><h3>基础信息、平台与状态</h3><div class="form-grid"><label>名称<input v-model="editing.name" required/></label><label>固定链接<input v-model="editing.slug" required/></label><label>版本<input v-model="editing.version"/></label><label>文件大小<input v-model="editing.fileSize"/></label><label>分类<select v-model.number="editing.categoryId"><option :value="null">未分类</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>发布状态<select v-model="editing.status"><option>DRAFT</option><option>PUBLISHED</option><option>OFFLINE</option></select></label><label>维护状态<select v-model="editing.maintenanceStatus"><option v-for="x in maintenance" :key="x.value" :value="x.value">{{x.label}}</option></select></label><label>排序值<input v-model.number="editing.sortOrder" type="number" min="0"/></label><label class="full">维护提示<textarea v-model="editing.maintenanceNote" placeholder="例如：已停止更新，仅建议旧设备使用"/></label><label class="full">下载说明<textarea v-model="editing.downloadNote" maxlength="1200" placeholder="例如：选择官方通道下载安装包；网盘通道请使用对应提取码。留空则显示默认说明。"/></label><fieldset class="full platform-choice"><legend>支持平台（可多选）</legend><label v-for="p in platforms" :key="p" class="checkbox"><input v-model="editing.platforms" type="checkbox" :value="p"/>{{p}}</label></fieldset><label class="checkbox"><input v-model="editing.featured" type="checkbox"/>首页推荐</label><label class="full">一句话简介<input v-model="editing.summary"/></label><label class="full">详细介绍<textarea v-model="editing.description"/></label><label class="full">标签（逗号分隔）<input :value="(editing.tags||[]).join(',')" @input="editing.tags=$event.target.value.split(',').map(x=>x.trim()).filter(Boolean)" placeholder="免费,开源,必备"/></label><label>定时发布<input v-model="editing.publishAt" type="datetime-local"/></label><label>定时下架<input v-model="editing.unpublishAt" type="datetime-local"/></label><label>定时取消推荐<input v-model="editing.unfeatureAt" type="datetime-local"/></label><label class="full">使用教程<textarea v-model="editing.tutorial"/></label><label class="full">更新日志<textarea v-model="editing.changelog"/></label></div></section><section class="editor-section"><h3>Logo 与截图</h3><label class="secondary-button"><Upload :size="16"/>上传 Logo<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="e=>uploadImage(e,url=>editing.coverImage=url)"/></label><img v-if="editing.coverImage" class="admin-image-preview" :src="editing.coverImage" alt="Logo"/><label class="secondary-button"><Upload :size="16"/>上传截图<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="e=>uploadImage(e,url=>editing.screenshots.push(url))"/></label><div class="screenshot-admin-grid"><article v-for="(image,index) in editing.screenshots" :key="image"><img :src="image" alt="截图"/><div><button type="button" @click="moveScreenshot(index,-1)">上移</button><button type="button" @click="moveScreenshot(index,1)">下移</button><button type="button" class="danger" @click="editing.screenshots.splice(index,1)">删除</button></div></article></div></section><section v-if="editing.id" class="editor-section"><h3><Link2 :size="18"/>下载渠道与健康检查</h3><div v-for="x in links" :key="x.id" class="managed-row"><input v-model="x.name"/><select v-model="x.channel_type"><option>OFFICIAL</option><option>DIRECT</option><option>BAIDU</option><option>QUARK</option><option>ALIYUN</option></select><input v-model="x.target_url"/><input v-model.number="x.sort_order" type="number"/><select v-model="x.status"><option>ACTIVE</option><option>DISABLED</option></select><button type="button" @click="saveLink(x)">保存</button><button type="button" @click="checkLink(x)">检测</button><button type="button" class="danger" @click="deleteLink(x)">删除</button><small v-if="x.last_check_message">{{x.last_check_status}} · {{x.last_check_message}}</small></div><div class="managed-row new-row"><input v-model="linkForm.name" placeholder="渠道名称"/><select v-model="linkForm.channelType"><option>OFFICIAL</option><option>DIRECT</option><option>BAIDU</option><option>QUARK</option><option>ALIYUN</option></select><input v-model="linkForm.targetUrl" placeholder="https:// 下载地址"/><input v-model.number="linkForm.sortOrder" type="number"/><select v-model="linkForm.status"><option>ACTIVE</option><option>DISABLED</option></select><button type="button" @click="saveLink(linkForm)">添加渠道</button></div></section><section v-if="editing.id" class="editor-section"><h3>版本历史</h3><div v-for="v in versions" :key="v.id" class="version-card"><div class="managed-row"><input v-model="v.version"/><input v-model="v.file_size"/><input v-model="v.changelog"/><input v-model.number="v.sort_order" type="number"/><select v-model="v.status"><option>ACTIVE</option><option>DISABLED</option></select><button type="button" @click="saveVersion(v)">保存</button><button type="button" class="danger" @click="deleteVersion(v)">删除</button></div><div v-for="x in v.links" :key="x.id" class="history-link"><span>{{x.name}} · {{x.target_url}}</span><button type="button" class="danger" @click="deleteVersionLink(v,x)">删除</button></div><div class="history-link"><input v-model="versionLinkForms[v.id].name" placeholder="链接名称"/><input v-model="versionLinkForms[v.id].targetUrl" placeholder="https:// 下载地址"/><button type="button" @click="addVersionLink(v)">添加历史下载链接</button></div></div><div class="managed-row new-row"><input v-model="versionForm.version" placeholder="历史版本号"/><input v-model="versionForm.fileSize" placeholder="文件大小"/><input v-model="versionForm.changelog" placeholder="更新说明"/><input v-model.number="versionForm.sortOrder" type="number"/><select v-model="versionForm.status"><option>ACTIVE</option><option>DISABLED</option></select><button type="button" @click="saveVersion(versionForm)">新增历史版本</button></div></section><section class="editor-section"><h3>SEO 与分享</h3><div class="form-grid"><label class="full">SEO 标题<input v-model="editing.seoTitle"/></label><label class="full">SEO 描述<textarea v-model="editing.seoDescription"/></label><label class="full">SEO 关键词<input v-model="editing.seoKeywords"/></label><label>分享标题<input v-model="editing.ogTitle"/></label><label>分享图片<input v-model="editing.ogImage"/></label><label class="full">分享描述<textarea v-model="editing.ogDescription"/></label></div></section></form></div>
<div v-if="editingSlide" class="modal-backdrop" @click.self="editingSlide=null"><form class="editor-modal category-modal" @submit.prevent="saveSlide"><div class="modal-heading"><h2>轮播图编辑</h2><button class="primary-button">保存</button></div><label>图片地址<input v-model="editingSlide.imageUrl" placeholder="上传图片或输入地址"/><input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadImage($event,url=>editingSlide.imageUrl=url)"/></label><label>标签<input v-model="editingSlide.kicker"/></label><label>标题<input v-model="editingSlide.title" required/></label><label>简介<textarea v-model="editingSlide.content"/></label><label>跳转类型<select v-model="editingSlide.targetType"><option value="CATEGORY">分类</option><option value="URL">外部链接</option><option value="NONE">不跳转</option></select></label><label>跳转目标<input v-model="editingSlide.targetValue" :placeholder="editingSlide.targetType==='CATEGORY'?'分类固定链接，如 office':'https://example.com'"/></label><label>排序值<input v-model.number="editingSlide.sortOrder" type="number"/></label><label class="checkbox"><input v-model="editingSlide.status" type="checkbox"/>首页启用</label></form></div>
<div v-if="editingCategory" class="modal-backdrop" @click.self="editingCategory=null"><form class="editor-modal category-modal" @submit.prevent="saveCategory"><div class="modal-heading"><h2>分类编辑</h2><button class="primary-button">保存</button></div><label>分类名称<input v-model="editingCategory.name" required/></label><label>固定链接<input v-model="editingCategory.slug" required/></label><label>排序值<input v-model.number="editingCategory.sortOrder" type="number"/></label><label class="checkbox"><input v-model="editingCategory.status" type="checkbox"/>前台启用</label></form></div>
<div v-if="editingAnnouncement" class="modal-backdrop" @click.self="editingAnnouncement=null"><form class="editor-modal category-modal" @submit.prevent="saveAnnouncement"><div class="modal-heading"><h2>公告编辑</h2><button class="primary-button">保存</button></div><label>公告标题<input v-model="editingAnnouncement.title" required/></label><label>公告内容<textarea v-model="editingAnnouncement.content"/></label><label>排序值<input v-model.number="editingAnnouncement.sortOrder" type="number"/></label><label class="checkbox"><input v-model="editingAnnouncement.status" type="checkbox"/>前台展示</label></form></div>
</template>
